        if cached:
            verify_str = f"PASS (cached from {source_cand}){err_str}"
        else:
            verify_str = f"PASS{err_str}"
        lines.append(f"- Verify: {verify_str}{elapsed_str}")

        # Result line
        cycles = meta.get("cycles") or {}
        cyc_parts = []
        for case in ("M1_P1", "M2_D1"):
            if case in cycles:
